<script setup lang="ts">
import { toPng } from 'html-to-image'
const defaults={partner:'DRIVER PRO',heading:'начните работать с wb taxi уже сегодня',description:'Подключаем водителей. Каждый день 10:00–19:00',benefit:'ваш график.\nваши возможности.',city:'Ташкент',website:'driver-pro.uz',phone:'+998 90 981 77 73',accent:'#7015ff',image:'https://images.unsplash.com/photo-1449965408869-eaa3f722e40d?auto=format&fit=crop&w=1400&q=85',logo:'',wbLogo:'',position:50}
const data=reactive({...defaults})
const preset=ref(0), tab=ref('Presets'), selected=ref('headline'), zoom=ref(75), exporting=ref(false), toast=ref(''), artboard=ref<HTMLElement>(), ready=ref(false)
const formats=[{name:'Square post',ratio:'1:1',w:1080,h:1080},{name:'Portrait post',ratio:'4:5',w:1080,h:1350},{name:'Story / Reel',ratio:'9:16',w:1080,h:1920},{name:'Landscape',ratio:'1.91:1',w:1200,h:628}]
const formatIndex=ref(0),format=computed(()=>formats[formatIndex.value])
const presets=['The introduction','The spotlight','The opportunity','The statement','The story','The essentials']
function notify(message:string){toast.value=message;setTimeout(()=>toast.value='',3500)}
function upload(event:Event,key:string){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>15*1024*1024){notify('Please choose a file under 15 MB');return}const reader=new FileReader();reader.onload=()=>{(data as any)[key]=reader.result;notify('Asset updated')};reader.readAsDataURL(file)}
function save(){try{localStorage.setItem('wb-bento',JSON.stringify({data,preset:preset.value,format:formatIndex.value}));notify('Project saved on this device')}catch{notify('Storage is full. Try using a smaller image.')}}
onMounted(()=>{try{const saved=JSON.parse(localStorage.getItem('wb-bento')||'null');if(saved){Object.assign(data,saved.data);preset.value=saved.preset;formatIndex.value=saved.format}}catch{}ready.value=true})
async function download(){if(!artboard.value)return;exporting.value=true;selected.value='';try{await nextTick();await document.fonts.ready;const node=artboard.value;const url=await toPng(node,{width:node.offsetWidth,height:node.offsetHeight,pixelRatio:format.value.w/node.offsetWidth,cacheBust:true});const a=document.createElement('a');a.download=`wb-bento-${format.value.w}x${format.value.h}.png`;a.href=url;a.click();notify('Your creative is ready')}catch{notify('Export failed. Try uploading a local photo instead.')}finally{exporting.value=false}}
</script>
<template>
<div class="studio">
 <header class="topbar"><a class="wordmark" href="#"><span class="wb">wb</span><span class="divider"></span>bento<span class="studio-label">STUDIO</span></a><div class="project-name">Untitled creative <span>⌄</span></div><div class="header-actions"><span class="status-dot"></span><span class="local-note">Local workspace</span><button class="button quiet" @click="save">Save project</button><button class="button primary" @click="download" :disabled="exporting">↓ <span>{{exporting?'Exporting…':'Export PNG'}}</span></button></div></header>
 <div class="workspace">
  <aside class="library"><div class="library-title"><h1>Make it yours.</h1><p>A little structure. A lot of possibility.</p></div><div class="tabs"><button v-for="name in ['Presets','Brand']" :class="{active:tab===name}" @click="tab=name">{{name}}</button></div>
   <template v-if="tab==='Presets'"><div class="section-caption">CHOOSE A LAYOUT <span>06</span></div><div class="preset-grid"><button v-for="(name,i) in presets" class="preset-card" :class="{active:preset===i}" @click="preset=i"><div class="preset-preview"><BentoCanvas :data="data" :preset="i" :format="formats[0]" miniature/></div><span>{{name}}</span><small v-if="preset===i">✓</small></button></div><div class="hint"><span>✧</span><p>Built to fit your story.<br/><strong>Every preset is ready to personalize.</strong></p></div></template>
   <template v-else><div class="section-caption">YOUR BRAND ASSETS</div><label class="upload-box">↥<strong>Upload partner logo</strong><small>SVG, PNG or WebP</small><input type="file" accept="image/svg+xml,image/png,image/webp" @change="upload($event,'logo')"/></label><label>Partner name<input v-model="data.partner"/></label><label class="upload-box">♧<strong>Official WB partner SVG</strong><small>Replaces the placeholder inside the locked pink block</small><input type="file" accept="image/svg+xml" @change="upload($event,'wbLogo')"/></label><p class="muted">The pink container, spacing and proportions are protected.</p></template>
   <div class="library-bottom"><span class="tiny-grid">▦</span> Good design starts with a good grid.</div>
  </aside>
  <main class="canvas-area"><div class="canvas-toolbar"><div><span class="small-dot"></span> Preview <span class="toolbar-divider">/</span> <span class="muted">{{presets[preset]}}</span></div><div class="format-tag">{{format.w}} × {{format.h}} px</div></div><div class="canvas-scroll"><div class="artboard-wrap" :style="{width:(formatIndex===2?330:formatIndex===3?700:560)*zoom/75+'px'}"><div ref="artboard" class="artboard"><BentoCanvas :data="data" :preset="preset" :format="format" :selected="selected" @select="selected=$event"/></div><div class="below-canvas"><span>✧ Click a block to edit its content</span><span>WB SANS</span></div></div></div><div class="canvas-bottom"><span>● <span>All the right pieces. Your own story.</span></span><div class="zoom-control"><button @click="zoom=Math.max(35,zoom-10)" aria-label="Zoom out">−</button><span>{{zoom}}%</span><button @click="zoom=Math.min(115,zoom+10)" aria-label="Zoom in">+</button></div></div></main>
  <aside class="inspector"><div class="inspector-heading"><h2>Creative settings</h2><span>☷</span></div><section><div class="section-caption">FORMAT</div><div class="format-grid"><button v-for="(f,i) in formats" :class="{active:formatIndex===i}" @click="formatIndex=i"><span class="ratio-icon" :style="{aspectRatio:f.w+'/'+f.h}"></span><strong>{{f.name}}</strong><small>{{f.ratio}}</small></button></div></section><section><div class="section-caption">CONTENT <span class="editable-badge">Editable</span></div><label>Headline<textarea v-model="data.heading" rows="3" @focus="selected='headline'"/></label><label>Supporting text<textarea v-model="data.description" rows="2" @focus="selected='headline'"/></label><label>Benefit block<textarea v-model="data.benefit" rows="2" @focus="selected='benefit'"/></label><div class="two-fields"><label>Location<input v-model="data.city"/></label><label>Website<input v-model="data.website"/></label></div><label>Phone number<input v-model="data.phone"/></label></section><section><div class="section-caption">PHOTO <span>JPG · PNG · WEBP</span></div><label class="photo-upload"><img :src="data.image"/><span>↥ Replace photo</span><input type="file" accept="image/*" @change="upload($event,'image')"/></label><label class="range-label">Image position <span>{{data.position}}%</span><input type="range" min="0" max="100" v-model="data.position"/></label></section><section><div class="section-caption">ACCENT COLOR</div><div class="swatches"><button v-for="color in ['#7015ff','#5421d6','#242424']" :style="{background:color}" :class="{chosen:data.accent===color}" @click="data.accent=color" :aria-label="'Use '+color">{{data.accent===color?'✓':''}}</button><label class="custom-color"><input type="color" v-model="data.accent"/>{{data.accent}}</label></div></section><div class="locked-note"><span>▣</span><div><strong>Always on brand</strong><p>The WB partner block is locked to keep your creative consistent.</p></div></div></aside>
 </div><Transition name="toast"><div v-if="toast" class="toast-message">✓ {{toast}}</div></Transition>
</div>
</template>
